The Typescript implementation of the algorithm is as follows:

`function binarySearch(
haystack: number[],
needle: number
): number {
let lo = 0;
let hi = haystack.length;
do {
const mid = Math.floor((hi + lo) / 2);
const v = haystack[mid];
if (v === needle) {
return mid;
} else if (v > needle) {
hi = mid;
} else {
lo = mid + 1; // we can exclude mid as we've already checked it
}
} while (lo < hi);
return -1;
}`
